head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > removeNode]<br/>트리 아이템 객체를 사용하여 특정 트리 아이템을 제거합니다.",
    "validation" : [
        "node(필수) 파라미터로 삭제 하려는 트리 아이템을 객체로 설정합니다.",
        "재귀적으로 모든 자식 트리 아이템을 함께 제거합니다.",
        "트리 아이템이 ItemSet 으로 정의된 경우 DataCollection 에 제거된 트리 아이템이 반영되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="아이템 클릭하여 아이템 삭제"', '', 'label1');    

    $c.gcm.createBasicTreeView('', eList);
}



scwin.getDataList = function () {
    let rtn = gdl_treeview.getRowCount();

    wf_body_bottom.getObj("scwin").setReturnValue("DataList rowcount : " + rtn);
}



scwin.btn_getText = function (e) {
    let rtn = target1.render.textContent;
    wf_body_bottom.getObj("scwin").setReturnValue("text: "+ rtn);


};



scwin.btn_removeNode_onclick = function (e) {
    target1.removeNode(target1.getSelectedNode());

    scwin.btn_getText();
};



scwin.target1_onclick = function (value, index) {
    scwin.btn_removeNode_onclick();
    scwin.getDataList()
}
